async function persist(next){ return window.desktop.replace(next); }
let settingsQueue=Promise.resolve();
function dispatch(action,message){if(action.type!=='settings')return applyAction(action,message);const task=settingsQueue.catch(()=>{}).then(()=>applyAction(action,message));settingsQueue=task;return task;}
async function applyAction(action,message){
  if(saving)throw new Error('Sauvegarde en cours. Réessaie dans un instant.');
  saving=true;
  try{state=await window.desktop.action(action);if(voice.enabled)voice.sync(state.settings).then(()=>{voice.networkDown=false;voice.applyTransmit();}).catch(e=>{voice.error=friendlyError(e);updateVoiceUI();});if(channelExperiment&&shared&&['join','create'].includes(action.type)){roomMode='text';channelsView.selectPending('squad:'+membership(state).id);page='operations';}if(action.type==='profile')localStorage.setItem('umbra-last-name',me().name);if(action.type==='settings'&&page==='settings'){syncSettingsControls();updateVoiceUI();}else render();if(channelExperiment&&shared&&['join','create'].includes(action.type))channelsView.refresh(state);if(message)toast(message);}finally{saving=false;}
}
function nav(target){if(target==='players'&&!me().admin)return;if(micMode!=='activity')stopMic();page=target;query='';filter='all';render();$('.content-scroll').scrollTop=0;if(target==='settings'&&settingsTab==='voice')refreshAudioDevices();}
function titlebar(){return `<header class="titlebar"><span class="titlebar-label">UMBRA</span><div class="window-controls"><button data-action="minimize" aria-label="Réduire">${icon('min')}</button><button data-action="maximize" aria-label="Agrandir">${icon('max')}</button><button data-action="close" aria-label="Fermer l’application">${icon('close')}</button></div></header>`;}
