  channelsView.saveFocus();const showRail=channelExperiment&&shared,railEnter=showRail&&!railWasVisible;railWasVisible=showRail;document.body.classList.toggle('channel-layout',showRail);
  const titles={operations:'Escouades',mine:'Mon escouade',command:'Communications',players:'Membres',settings:'Réglages',detail:'Escouade'};
  $('#app').innerHTML=`${titlebar()}<div class="shell"><aside class="sidebar"><div class="brand">${brand}<div><div class="brand-name">UMBRA</div><div class="brand-sub">WARDOGS COMPANION</div></div></div>
  <nav aria-label="Navigation principale">${[['operations','grid','Escouades'],['mine','squad','Mon escouade'],['players','users','Membres'],['command','radio','Communications']].filter(([id])=>id!=='players'||me().admin).map(([id,ic,label])=>`<button class="nav-item ${page===id || (id==='operations'&&page==='detail')?'active':''}" data-nav="${id}">${icon(ic)}${label}</button>`).join('')}</nav>${showRail?`<div class="channel-rail ${railEnter?'rail-enter':''}" id="channel-rail">${channelRail()}</div>`:''}
  <div class="side-bottom"><button class="nav-item" data-action="tutorial">${icon('info')}Guide rapide</button><button class="nav-item ${page==='settings'?'active':''}" data-nav="settings">${icon('settings')}Réglages</button>${shared?voiceSidebar():`<div class="local-micbar"><button data-action="activity" class="mic-activity-toggle" title="Détection locale uniquement, aucun son transmis">${icon('mic')}<span>${micMode==='activity'?'Micro local actif':'Activer le micro local'}</span>${speaking(state.currentUserId)}</button></div>`}<button class="profile" data-action="profile">${avatar(me())}<span><strong>${displayName(me())}</strong><small>${escape(gradeNames(me()).join(' · ')||'Membre')}</small></span>${icon('edit')}</button><button class="logout-button" data-action="logout">${icon('logout')}Se déconnecter</button></div></aside>
  <section class="workspace"><header class="topbar"><div class="breadcrumbs">${page==='operations'&&channelExperiment&&roomMode==='text'?'Salons textuels':titles[page]}</div><div class="top-info"><span class="top-update-slot" data-top-update></span><span class="offline-dot"></span><span data-top-voice-status>${shared?'Serveur de la team':'Mode hors ligne'}</span><span class="build-label">P.H.A.N.T.O.M</span></div></header><main class="content-scroll">${page==='operations'?channelExperiment&&roomMode==='text'?textPage():operations():page==='mine'?mine?detail(mine):emptyMine():page==='detail'?squad(selected)?detail(squad(selected)):emptyMine():page==='command'?communicationPage():page==='players'?players():settings()}<footer class="footer"><span>UMBRA · ${escape(appVersion)}</span><span>${shared?'Synchronisé avec la team':'Enregistré sur ce PC'}</span></footer></main></section></div>`;
 updateVoiceUI();updateTopButton();channelsView.mount();if(page==='settings')$('.content-scroll').scrollTop=settingsScroll;
