function railVoicePeople(id){return voiceUsers.filter(v=>v.channels.some(c=>c.kind==='primary'&&(id==='lobby'?!c.squadId:c.squadId===id))).map(v=>player(v.id)).filter(Boolean).map(p=>`<button class="rail-person" data-action="viewProfile" data-player="${escape(p.id)}">${speaking(p.id)}<span>${displayName(p)}</span></button>`).join('');}
function chatPing(message){if(!state)return;const p=player(message.authorId),c=channelsView.channels.find(c=>c.id===message.channelId);toast((p?.name||'Un joueur')+' te mentionne dans #'+(c?.name||'un salon'));if(state.settings.notificationSounds&&state.settings.soundsVolume>0){const ctx=new AudioContext(),gain=ctx.createGain();gain.gain.value=.12*state.settings.soundsVolume/100*state.settings.outputVolume/100;if(state.settings.output&&ctx.setSinkId)ctx.setSinkId(state.settings.output).catch(()=>{});gain.connect(ctx.destination);for(const [frequency,offset]of [[740,0],[980,.12]]){const osc=ctx.createOscillator();osc.frequency.value=frequency;osc.connect(gain);osc.start(ctx.currentTime+offset);osc.stop(ctx.currentTime+offset+.1);}setTimeout(()=>ctx.close(),600);}}
function textPage(){return `${!membership(state)&&shared?`<div class="chat-inline-channels">${channelMenu.ordered(channelsView.channels).map(c=>`<button class="btn ghost ${channelsView.selected===c.id?'active':''}" data-chat-select="${escape(c.id)}"># ${escape(c.name)}</button>`).join('')}${me().admin?'<button class="btn ghost" data-chat-create>+ Créer un salon</button>':''}</div>`:''}${channelsView.render({state,escape,icon,shared})}`;}
