function reactionDialog(id){if(!channelsView.messages.some(m=>m.id===id))return;showDialog('Ajouter une réaction',`<div class="reaction-picker">${Object.values(EMOJIS).flat().map(emoji=>`<button type="button" data-action="messageReaction" data-message="${escape(id)}" data-emoji="${escape(emoji)}" aria-label="${escape(emoji)}">${escape(emoji)}</button>`).join('')}</div>`,null,()=>{});}
