async function showPinnedMessages(){const channelId=channelsView.selected,result=await window.desktop.chat('pins',{channelId});if(channelId!==channelsView.selected)return;showDialog('Messages épinglés',result.messages.length?`<div class="pinned-messages">${result.messages.map(m=>`<div class="pinned-message"><strong>${escape(player(m.authorId)?.name||'Ancien membre')}</strong><p>${escape(m.text.slice(0,280)||'Pièce jointe')}</p>${button('Ouvrir le message','jumpPin',`data-message="${escape(m.id)}"`,'ghost')}</div>`).join('')}</div>`:'<p class="dialog-description">Aucun message épinglé dans ce salon.</p>',null,()=>{});}
function deleteTextChannel(id){const c=channelsView.channels.find(c=>c.id===id);if(!c?.canDelete)return;confirmDialog('Supprimer #'+c.name+' ?','Les messages et fichiers de ce salon seront définitivement supprimés.','Supprimer',async()=>{await window.desktop.chat('delete',{channelId:id});await channelsView.refresh(state);toast('Salon supprimé.');});}
