 showDialog('Modifier le salon',`<label class="field"><span>Nom</span><input name="name" required maxlength="40" value="${escape(c.name)}"></label><label class="field"><span>Description</span><input name="description" maxlength="200" value="${escape(c.description)}"></label>${c.custom?`<label class="field"><span>Accès</span><select name="scope"><option value="team" ${c.scope==='team'?'selected':''}>Toute la team</option>${state.squads.map(q=>`<option value="squad:${escape(q.id)}" ${q.id===c.squadId?'selected':''}>Membres de ${escape(q.name)} + admins</option>`).join('')}</select></label><label class="field"><span>Publication des messages</span><select name="publication"><option value="all" ${!c.announcements?'selected':''}>Tous les lecteurs</option><option value="command" ${c.announcements?'selected':''}>Commandement et admins</option></select></label><p class="settings-note">Changer l’accès s’applique aussi aux messages et médias déjà présents dans ce salon.</p>`:'<p class="settings-note">Les accès de ce salon automatique restent liés à sa fonction.</p>'}`,'Enregistrer',async data=>{
  const choice=data.get('scope'),values={channelId:id,name:data.get('name'),description:data.get('description'),...(c.custom?{scope:choice==='team'?'team':'squad',squadId:choice==='team'?null:choice.slice(6),announcements:data.get('publication')==='command'}:{})};
  await window.desktop.chat('update',values);await channelsView.refresh(state);toast('Salon mis à jour.');
 });
