function cards(){
 const qs=state.squads.filter(q=>(filter==='all'||filter==='open'&&q.slots.some(t=>!t.playerId)||q.type===filter)&&[q.name,q.type,...q.slots.map(t=>t.role)].some(t=>t.toLocaleLowerCase('fr').includes(query.toLocaleLowerCase('fr'))));
 const free=qs.filter(q=>!operationForSquad(state,q.id));
 const groups=state.operations.map(o=>{
   const joined=qs.filter(q=>o.squadIds.includes(q.id));
   return `<section class="operation-group" data-operation-group="${escape(o.id)}" aria-label="Opération ${escape(o.name)}">${operationBanner(o,true)}<div class="operation-squads">${joined.length?`<div class="squad-grid">${joined.map(card).join('')}</div>`:`<p class="operation-empty">${o.squadIds.length?'Aucune escouade ne correspond aux filtres.':'Aucune escouade inscrite à cette opération.'}</p>`}</div></section>`;
 }).join('');
 const freeSection=free.length?`<section class="free-squads"><h2>Escouades libres</h2><div class="squad-grid">${free.map(card).join('')}</div></section>`:'';
 if(groups||freeSection)return groups+freeSection;
 return `<div class="empty-state">${icon('search')}<h3>${state.squads.length?'Aucune escouade trouvée':'Le terrain est libre.'}</h3><p>${state.squads.length?'Essaie un autre nom ou un autre poste.':'Crée ta première escouade pour préparer l’opération.'}</p></div>`;
}
function card(q){
 const members=q.slots.filter(t=>t.playerId),free=q.slots.length-members.length,appearance=squadAppearance(q);
 return `<article class="squad-card" style="--squad-color:${appearance.color}" data-squad="${escape(q.id)}"><div class="card-head"><div class="squad-emblem">${icon(appearance.icon)}</div><div class="card-title"><h3>${escape(q.name)}</h3><p>${escape(q.type)} · ${escape(q.mood)}</p></div><span class="card-count">${members.length}<small> / ${q.slots.length}</small></span></div><div class="squad-members">${members.map(t=>`<div class="squad-member-row">${speaking(t.playerId)}<button class="name-link" data-action="viewProfile" data-player="${escape(t.playerId)}">${displayName(player(t.playerId))}</button>${q.leaderId===t.playerId?`<span class="member-chief" title="Chef d’escouade">${icon('crown')}</span>`:''}<span class="member-role">${escape(t.role)}</span></div>`).join('')}</div><div class="card-foot"><span class="subtext">${free?`${free} place${free>1?'s':''} libre${free>1?'s':''}`:'Complète'}${members.some(t=>t.playerId===state.currentUserId)?' · Ton escouade':''}</span><div class="card-actions">${!membership(state)&&free?button('Rejoindre','chooseSlot',`data-id="${escape(q.id)}"`,'gold'):shared&&members.some(t=>t.playerId===state.currentUserId)?squadVoiceButton(q):''}${button('Ouvrir '+icon('arrow'),'detail',`data-id="${escape(q.id)}"`,'ghost')}</div></div></article>`;
}
function squadVoiceButton(q){return button(icon('headset')+'Connexion','voiceSquad',`data-id="${escape(q.id)}" data-squad-connect="${escape(q.id)}"`,'gold');}
function lobby(){return `<section class="lobby-panel"><div class="lobby-heading">${icon('headset')}<div><h2>Accueil vocal</h2><p class="subtext">Pour les joueurs sans escouade.</p></div>${!membership(state)?button('Rejoindre l’accueil','voiceLobby','','ghost'):''}</div><div class="lobby-members" data-lobby-members>${lobbyMembers()}</div></section>`;}
function lobbyMembers(){const people=voiceUsers.filter(v=>v.channels.some(c=>c.kind==='primary'&&!c.squadId&&!c.operationId)).map(v=>player(v.id)).filter(Boolean);return people.length?people.map(p=>`<button class="person-chip" data-action="viewProfile" data-player="${escape(p.id)}">${speaking(p.id)}${displayName(p)}</button>`).join(''):'<span class="subtext">Personne dans l’accueil.</span>';}
function emptyMine(){return `<div class="page-heading"><div><h2>Mon escouade</h2><p class="subtext">Ta place dans l’opération.</p></div></div><div class="empty-state">${icon('squad')}<h3>Tu n’as pas encore d’escouade.</h3><p>Rejoins un poste disponible dans une équipe ou forme ta propre escouade avec la composition de ton choix.</p>${button('Parcourir les escouades','operations','','gold')} ${button('Créer mon escouade','create')}</div>`;}
function detail(q){
 const manage=canManage(state,q),own=membership(state)?.id===q.id,appearance=squadAppearance(q);
 return `<section class="page squad-detail"><div class="page-heading"><h1>${own?'Mon escouade':'Escouade'}</h1>${button('Retour aux escouades','operations','','ghost')}</div><div class="detail-hero" style="--squad-color:${appearance.color}"><div class="squad-emblem">${icon(appearance.icon)}</div><div class="detail-title"><h2>${escape(q.name)}</h2><p>${escape(q.type)} · ${escape(q.mood)} · ${q.slots.filter(t=>t.playerId).length}/${q.slots.length} places occupées</p></div><div class="heading-actions">${shared&&own?squadVoiceButton(q):shared&&me().admin?button(icon('headset')+'Visiter le vocal','voiceVisit',`data-id="${escape(q.id)}"`,'ghost'):''}${manage?button(icon('edit')+'Modifier','edit',`data-id="${escape(q.id)}"`):''}</div></div><div class="panel"><div class="panel-heading">Membres <span class="subtext">Chef : ${displayName(player(q.leaderId))}${q.deputyId?' · Adjoint : '+escape(player(q.deputyId).name):''}</span></div><table class="data-table squad-composition"><thead><tr><th>Joueurs</th><th>Poste</th><th>Actions</th></tr></thead><tbody>${q.slots.map(t=>`<tr><td>${t.playerId?`<div class="member" data-player="${escape(t.playerId)}">${speaking(t.playerId)}<div><button class="name-link" data-action="viewProfile" data-player="${escape(t.playerId)}">${displayName(player(t.playerId))}</button>${q.leaderId===t.playerId?' <span class="tag gold">CHEF</span>':q.deputyId===t.playerId?' <span class="tag">ADJOINT</span>':''}${t.playerId===state.currentUserId?' <span class="tag muted">VOUS</span>':''}</div></div>`:'<span class="available">Place disponible</span>'}</td><td>${escape(t.role)}</td><td><div class="actions">${!t.playerId?`${!membership(state)?button('Rejoindre','join',`data-id="${escape(q.id)}" data-slot="${escape(t.id)}"`,'gold'):''}${manage?button('Affecter','assign',`data-id="${escape(q.id)}" data-slot="${escape(t.id)}"`):''}`:manage?button('Gérer','member',`data-id="${escape(q.id)}" data-player="${escape(t.playerId)}"`):''}</div></td></tr>`).join('')}</tbody><tbody data-squad-guests="${escape(q.id)}">${voiceVisitors(q)}</tbody></table></div><div class="setting-actions squad-bottom-actions">${own&&q.leaderId!==state.currentUserId?button(icon('logout')+'Quitter l’escouade','leave',`data-id="${escape(q.id)}"`,'ghost'):''}${manage?button(icon('trash')+'Dissoudre l’escouade','delete',`data-id="${escape(q.id)}"`,'danger'):''}</div></section>`;
}
function command(){return `<div class="page"><div class="page-heading"><div><div class="eyebrow">Réseaux de communication</div><h2 style="margin-top:10px">Communications</h2><p class="subtext">La bonne information, aux bonnes personnes.</p></div><span class="tag gold">APERÇU · VOCAL À CONNECTER</span></div><div class="notice">Les règles ci-dessous définissent le fonctionnement prévu. Cette version ne transmet aucun son et n’active aucune touche radio globale.</div><div class="diagram">${[['squad','Réseau squad','Tous les membres parlent à leur escouade. Un admin peut visiter le vocal sans occuper de place.','MEMBRES + ADMIN INVITÉ'],['radio','Réseau leaders','Chefs, adjoints et commandants coordonnent l’opération, sans quitter leur squad.','CHEFS · ADJOINTS · COMMANDEMENT'],['users','Annonce générale','Le commandement s’adresse à toutes les escouades. Le rôle admin seul ne donne pas ce droit.','COMMANDEMENT UNIQUEMENT']].map(([ic,t,p,tag])=>`<article class="network-card">${icon(ic)}<h3>${t}</h3><p>${p}</p><span class="tag">${tag}</span></article>`).join('')}</div><section class="panel"><div class="panel-heading">CHEFS D’ESCOUADE <span>${state.squads.length} AFFECTÉS</span></div><div class="command-leaders">${state.squads.length?state.squads.map(q=>`<button class="leader-chip" data-action="detail" data-id="${escape(q.id)}">${speaking(q.leaderId)}<span><strong>${displayName(player(q.leaderId))}</strong><small>${escape(q.name)}</small></span>${icon('chevron')}</button>`).join(''):'<p class="subtext">Les chefs apparaîtront ici lorsque les premières escouades seront créées.</p>'}</div></section><section class="panel"><div class="panel-heading">VOS DROITS LOCAUX</div><div class="panel-body"><p class="settings-note">${escape(me().name)} · ${me().admin?'Administration autorisée':'Membre'} · ${leaderAccess(state)?'Rôle réseau leaders autorisé':'Pas de rôle réseau leaders'} · ${me().commander?'Commandant':'Pas de rôle commandant'}</p><p class="subtext">L’administration gère les effectifs. Le commandement dirige l’opération. Ces responsabilités restent distinctes.</p></div></section></div>`;}
function players(){if(!me().admin)return '';return `<div class="page"><div class="page-heading"><div><h1>Membres</h1><p class="subtext">${shared?'Les membres de la team, synchronisés avec le serveur.':'Comptes créés sur ce PC.'}</p></div><span class="member-total">${state.players.length} membre${state.players.length>1?'s':''}</span></div><div class="panel"><table class="data-table"><thead><tr><th>Joueur</th><th>Escouade</th><th>Responsabilités</th><th></th></tr></thead><tbody>${state.players.map(p=>{const q=membership(state,p.id);return `<tr><td><div class="member" data-player="${escape(p.id)}">${speaking(p.id)}<span><button class="name-link" data-action="viewProfile" data-player="${escape(p.id)}">${displayName(p)}</button> ${p.id===state.currentUserId?'<span class="tag muted">Vous</span>':''}</span></div></td><td>${q?escape(q.name):'<span class="subtext">Non affecté</span>'}</td><td>${p.admin?'<span class="tag">Admin</span> ':''}${p.commander?'<span class="tag">Commandant</span> ':''}${p.squadLeader?'<span class="tag">Squad leader</span> ':''}${q?.leaderId===p.id?'<span class="tag">Chef</span>':q?.deputyId===p.id?'<span class="tag">Adjoint</span>':!p.admin&&!p.commander&&!p.squadLeader?'<span class="subtext">Membre</span>':''}</td><td>${me().admin?`<div class="actions">${button('Permissions','rights',`data-player="${escape(p.id)}"`,'ghost')}${button('Mot de passe','passwordResetCode',`data-player="${escape(p.id)}" title="Réinitialiser le mot de passe"`,'ghost')}</div>`:''}</td></tr>`;}).join('')}</tbody></table></div><p class="local-warning">${shared?'Les nouveaux membres créent leur compte avec le code de la team.':'Pour ajouter une personne : se déconnecter, puis créer son compte.'}</p></div>`;}
function settings(){
 const tabs=[['voice','headset','Voix & vidéo'],['shortcuts','radio','Raccourcis'],['account','users','Mon compte'],['application','settings','Application']];
 return `<section class="page settings-page"><div class="page-heading"><div><h1>Réglages</h1><p class="subtext">Tout ce qu’il te faut avant de rejoindre le vocal.</p></div></div><div class="settings-layout"><nav class="settings-nav" aria-label="Catégories des réglages">${tabs.map(([id,ic,label])=>`<button data-action="settingsTab" data-tab="${id}" class="${settingsTab===id?'active':''}" aria-current="${settingsTab===id?'page':'false'}">${icon(ic)}${label}</button>`).join('')}</nav><div class="settings-body">${settingsTab==='voice'?audioPanel()+voiceSettings():settingsTab==='shortcuts'?shortcutsPanel():settingsTab==='account'?`<div class="panel"><div class="panel-heading">Mon compte</div><div class="panel-body"><div class="account-summary">${avatar(me())}<div><strong>${displayName(me())}</strong><p class="subtext">${shared?'Compte de la team':'Compte sur ce PC'}</p></div></div><div class="setting-actions">${button('Personnaliser mon profil','profile')}${button('Se déconnecter','logout','','ghost')}</div></div></div>`:experimentPanel()+networkPanel()+updatePanel()+`<div class="panel"><div class="panel-heading">Sauvegardes</div><div class="panel-body"><p class="settings-note">Tes modifications sont enregistrées automatiquement. L’export contient les escouades, jamais les mots de passe.</p><div class="setting-actions">${button(icon('download')+'Exporter','export')}${me().admin?button(icon('upload')+'Importer','import'):''}</div></div></div><button class="help-link" data-action="tutorial">${icon('info')}Revoir le guide rapide</button>`}</div></div></section>`;
}
const modal=$('#modal');
function showDialog(title,body,submitLabel,onSubmit){
 if(modal.open)modal.close();
 modal.innerHTML=`<form id="dialog-form"><header class="modal-head"><h2>${escape(title)}</h2><button type="button" class="modal-close" data-action="dismiss" aria-label="Fermer">${icon('close')}</button></header><div class="modal-body">${body}<p class="error-text" id="dialog-error" role="alert"></p></div><footer class="modal-foot"><button type="button" class="btn ghost" data-action="dismiss">${submitLabel?"Annuler":"Fermer"}</button>${submitLabel?`<button type="submit" class="btn gold">${escape(submitLabel)}</button>`:''}</footer></form>`;
 $('#dialog-form').addEventListener('submit',async e=>{e.preventDefault();const submit=e.target.querySelector('[type=submit]');if(!submit)return;submit.disabled=true;try{await onSubmit(new FormData(e.target));modal.close();}catch(error){$('#dialog-error').textContent=friendlyError(error);}finally{submit.disabled=false;}});
 modal.showModal();
}
function confirmDialog(title,text,label,fn){showDialog(title,`<p class="dialog-description">${escape(text)}</p>`,label,fn);}
const formatSchedule = value => value ? new Intl.DateTimeFormat('fr-FR',{dateStyle:'medium',timeStyle:'short',timeZone:'UTC'}).format(new Date(value+'Z'))+' · Paris' : 'Horaire à définir';
function operationForm(o){
 showDialog(o?'Modifier l’opération':'Créer une opération',`<label class="field"><span>Nom de l’opération</span><input name="name" required maxlength="60" value="${escape(o?.name||'')}" placeholder="Nom de l’opération"></label><div class="form-row"><label class="field"><span>Type</span><select name="kind">${optionList(OPERATION_TYPES,o?.type)}</select></label><label class="field"><span>Horaire · heure de Paris</span><input name="startsAt" type="datetime-local" value="${escape(o?.startsAt||'')}"></label></div><label class="field"><span>Serveur de jeu</span><input name="server" maxlength="120" value="${escape(o?.server||'')}" placeholder="Nom ou adresse du serveur"></label><label class="field"><span>Description</span><textarea name="description" maxlength="1500" placeholder="Objectif, consignes et informations utiles">${escape(o?.description||'')}</textarea></label>${o?`<label class="field"><span>Phase</span><select name="phase">${optionList(OPERATION_PHASES,o.phase)}</select></label>`:'<p class="subtext">Si tu es chef, ta squad sera inscrite automatiquement lorsqu’elle n’a pas déjà d’opération.</p>'}`,o?'Enregistrer':'Créer l’opération',async data=>dispatch({type:o?'operationEdit':'operationCreate',operationId:o?.id,name:data.get('name'),kind:data.get('kind'),startsAt:data.get('startsAt'),server:data.get('server'),description:data.get('description'),phase:data.get('phase')},o?'Opération mise à jour.':'Opération créée.'));
}
function operationBanner(o,full=false){
 const mine=membership(state),enrolled=mine&&o.squadIds.includes(mine.id),leader=mine?.leaderId===state.currentUserId;
 const qs=state.squads.filter(q=>o.squadIds.includes(q.id));
 const planned=qs.filter(q=>o.briefingSquadIds.includes(q.id)),participants=planned.flatMap(q=>q.slots.filter(t=>t.playerId).map(t=>player(t.playerId)));
 const otherOperation=mine&&operationForSquad(state,mine.id);
 const joinedElsewhere=otherOperation&&!enrolled;
 return `<section class="operation-banner" data-operation="${escape(o.id)}"><div class="operation-top"><div><div class="operation-eyebrow">${icon('radio')}Salle de briefing <span class="tag">${escape(o.phase)}</span></div><h3>${escape(o.name)}</h3><p class="operation-meta">${escape(o.type)} · ${escape(o.server||'Serveur à définir')} · ${escape(formatSchedule(o.startsAt))}</p></div><div class="operation-actions">${canManageOperation(state,o)?button(icon('edit')+'Modifier','editOperation',`data-id="${escape(o.id)}"`,'ghost'):''}${leader&&!enrolled&&o.phase!=='Terminée'?button('Rejoindre avec ma squad','joinOperation',`data-id="${escape(o.id)}" ${joinedElsewhere?`disabled title="Quitte d’abord l’opération ${escape(otherOperation.name)}"`:''}`):''}${leader&&enrolled?button(o.briefingSquadIds.includes(mine.id)?'Sortir du briefing':'Rassembler ma squad','briefing',`data-id="${escape(o.id)}" ${o.phase==='Terminée'?'disabled':''}`,'gold'):''}${leader&&enrolled?button('Quitter l’opération','leaveOperation',`data-id="${escape(o.id)}"`,'ghost'):''}</div></div>${o.description?`<p class="operation-description">${escape(o.description)}</p>`:''}<div class="operation-bottom"><span>${qs.length} squad${qs.length>1?'s':''} inscrite${qs.length>1?'s':''} · ${participants.length} joueur${participants.length>1?'s':''} attendu${participants.length>1?'s':''} au briefing</span><span>${shared?`<span class="tag" data-operation-presence="${escape(o.id)}">0 en vocal</span>`:''}</span><span class="operation-local">${shared?'Briefing partagé · déplacement vocal des squads':'Préparation locale · vocal non connecté'}</span></div>${participants.length?`<details class="briefing-roster"><summary>Voir les participants attendus</summary><div class="briefing-people">${participants.map(p=>`<button class="person-chip" data-action="viewProfile" data-player="${escape(p.id)}">${speaking(p.id)}${displayName(p)}</button>`).join('')}</div></details>`:''}${full?`<div class="operation-foot">${canManageOperation(state,o)?button(icon('trash')+'Supprimer l’opération','deleteOperation',`data-id="${escape(o.id)}"`,'ghost'):''}</div>`:''}</section>`;
}
function profileCard(p,editing=false){const a=profileAppearance(p);return `<section class="profile-card" style="${profileBackground(p)}"><div class="profile-banner">${editing?`<button type="button" data-profile-image="banner" class="profile-image-hit profile-banner-hit" aria-label="Changer la bannière" title="Changer la bannière">${a.banner?`<img src="${escape(a.banner)}" alt="Bannière de ${escape(p.name)}">`:''}<span class="profile-image-overlay">${icon('edit')}Changer la bannière</span></button>${a.banner?'<button type="button" data-profile-remove="banner" class="profile-image-remove" title="Retirer la bannière" aria-label="Retirer la bannière">×</button>':''}`:a.banner?`<img src="${escape(a.banner)}" alt="Bannière de ${escape(p.name)}">`:''}</div><div class="profile-card-body">${editing?`<div class="profile-avatar-editor"><button type="button" data-profile-image="picture" class="profile-image-hit profile-avatar-hit" aria-label="Changer la photo de profil" title="Changer la photo de profil">${avatar(p)}<span class="profile-image-overlay">${icon('edit')}</span></button>${p.picture?'<button type="button" data-profile-remove="picture" class="profile-avatar-remove" aria-label="Retirer la photo de profil" title="Retirer la photo de profil">×</button>':''}</div>`:avatar(p)}<h3 data-player="${escape(p.id)}">${displayName(p)}</h3>${gradeNames(p).length?`<div class="profile-grades">${gradeNames(p).map(g=>`<span class="tag">${escape(g)}</span>`).join(' ')}</div>`:''}<div class="profile-specialties"><span>${roleIcons[a.primaryRole]}${escape(a.primaryRole)} · Principal</span>${a.secondaryRole?`<span>${roleIcons[a.secondaryRole]}${escape(a.secondaryRole)} · Secondaire</span>`:''}</div><p class="profile-bio">${escape(p.description||'Aucune description pour le moment.')}</p></div></section>`;}
function profileForm(){
 const appearance=profileAppearance(me());let picture=me().picture||'',banner=appearance.banner,primaryRole=appearance.primaryRole,secondaryRole=appearance.secondaryRole;
 const rolePicker=(kind,value)=>`<div class="profile-role-picker" data-picker="${kind}">${(kind==='secondaryRole'?['',...PROFILE_ROLES]:PROFILE_ROLES).map(role=>`<button type="button" data-profile-select="${kind}" data-role="${escape(role)}" class="${value===role?'active':''}" aria-pressed="${value===role}">${role?roleIcons[role]:icon('close')}<span>${escape(role||'Aucun')}</span></button>`).join('')}</div>`;
 showDialog('Mon profil',`<div id="profile-live-preview">${profileCard(me(),true)}</div><p class="subtext profile-image-hint">Clique sur ta photo ou ta bannière pour les changer · PNG, JPG ou WebP, 5 Mo maximum.</p><label class="field"><span>Pseudo</span><input name="name" required maxlength="32" value="${escape(me().name)}"></label><label class="field"><span>Description</span><textarea name="description" maxlength="280" placeholder="Quelques mots sur toi, ton style de jeu…">${escape(me().description||'')}</textarea><small>280 caractères maximum.</small></label><div class="profile-gradient-controls"><label class="field"><span>Première couleur</span><span class="profile-color-control"><span class="profile-color-swatch" data-color-swatch="gradientStart" style="background:${appearance.gradient.start}"></span><output data-color-hex="gradientStart">${appearance.gradient.start}</output><input type="color" name="gradientStart" aria-label="Première couleur du dégradé" value="${appearance.gradient.start}"></span></label><label class="field"><span>Seconde couleur</span><span class="profile-color-control"><span class="profile-color-swatch" data-color-swatch="gradientEnd" style="background:${appearance.gradient.end}"></span><output data-color-hex="gradientEnd">${appearance.gradient.end}</output><input type="color" name="gradientEnd" aria-label="Seconde couleur du dégradé" value="${appearance.gradient.end}"></span></label><label class="field"><span>Orientation</span><input type="range" name="gradientAngle" min="0" max="360" value="${appearance.gradient.angle}"></label></div><div class="field"><span>Spécialité principale</span>${rolePicker('primaryRole',primaryRole)}</div><div class="field"><span>Spécialité secondaire</span>${rolePicker('secondaryRole',secondaryRole)}</div><p class="settings-note">Ces spécialités sont affichées sur ton profil. Ton poste dans l’escouade se choisit séparément.</p>`,'Enregistrer',async data=>dispatch({type:'profile',name:data.get('name'),description:data.get('description'),picture,banner,primaryRole,secondaryRole,profileGradient:{start:data.get('gradientStart'),end:data.get('gradientEnd'),angle:Number(data.get('gradientAngle'))}},'Profil enregistré.'));
 const preview=()=>{const form=$('#dialog-form');if(!form)return;const p={...me(),picture,banner,primaryRole,secondaryRole,name:form.elements.name.value,description:form.elements.description.value,profileGradient:{start:form.elements.gradientStart.value,end:form.elements.gradientEnd.value,angle:Number(form.elements.gradientAngle.value)}};$('#profile-live-preview').innerHTML=profileCard(p,true);for(const name of ['gradientStart','gradientEnd']){const color=form.elements[name].value;form.querySelector('[data-color-swatch="'+name+'"]').style.backgroundColor=color;form.querySelector('[data-color-hex="'+name+'"]').value=color;}};
 let imagePicking=false;$('#dialog-form').addEventListener('click',async e=>{const button=e.target.closest('[data-profile-image],[data-profile-remove]');if(!button||imagePicking)return;const kind=button.dataset.profileImage||button.dataset.profileRemove;if(button.dataset.profileRemove){if(kind==='picture')picture='';else banner='';preview();return;}imagePicking=true;button.disabled=true;try{const selected=await window.desktop[kind==='picture'?'choosePicture':'chooseBanner']();if(selected!==null){if(kind==='picture')picture=selected;else banner=selected;preview();}}catch(error){if($('#dialog-error'))$('#dialog-error').textContent=friendlyError(error);}finally{imagePicking=false;button.disabled=false;}});
 $('#dialog-form').addEventListener('input',preview);
 $('#dialog-form').addEventListener('click',e=>{const b=e.target.closest('[data-profile-select]');if(!b)return;const role=b.dataset.role;if(b.dataset.profileSelect==='primaryRole'){primaryRole=role;if(secondaryRole===role)secondaryRole='';}else secondaryRole=role===primaryRole?'':role;for(const btn of $('#dialog-form').querySelectorAll('[data-profile-select]')){const active=btn.dataset.role===(btn.dataset.profileSelect==='primaryRole'?primaryRole:secondaryRole);btn.classList.toggle('active',active);btn.setAttribute('aria-pressed',active);}preview();});
}
function viewProfile(id){if(id===state.currentUserId)return profileForm();const p=player(id),q=membership(state,id);if(!p)return;showDialog('Profil',`<div class="profile-view">${profileCard(p)}</div><p class="subtext profile-squad-label">${q?escape(q.name):'Sans escouade'}</p>`,null,()=>{});}
const optionList=(values,value)=>values.map(t=>`<option value="${escape(t)}" ${t===value?'selected':''}>${escape(t)}</option>`).join('');

function squadForm(q){
 if(!q&&membership(state))return toast('Quitte ton escouade actuelle avant d’en créer une nouvelle.',true);
 let appearance=squadAppearance(q);
 let slots=q?structuredClone(q.slots):[{id:uid(),role:'Infanterie',playerId:state.currentUserId}];
 const customValues=new Map(slots.filter(t=>roleChoice(t.role)===CUSTOM_ROLE).map(t=>[t.id,t.role]));
 const customSlots=new Set(customValues.keys());
 showDialog(q?'Modifier l’escouade':'Créer une escouade',`<label class="field"><span>Nom de l’escouade</span><input name="name" required maxlength="40" placeholder="Ex. INFANTERIE ALPHA" value="${escape(q?.name||'')}"></label><div class="form-row"><label class="field"><span>Type d’escouade</span><select name="kind">${optionList(TYPES,q?.type)}</select></label><label class="field"><span>Ambiance du vocal</span><select name="mood">${optionList(MOODS,q?.mood)}</select></label></div><div class="appearance-editor"><fieldset><legend>Icône</legend><div class="appearance-icons">${SQUAD_ICONS.map(([id,label])=>`<button type="button" class="appearance-choice ${appearance.icon===id?'selected':''}" data-squad-icon="${id}" aria-label="${label}" aria-pressed="${appearance.icon===id}" title="${label}">${icon(id)}</button>`).join('')}</div></fieldset><fieldset><legend>Couleur du contour</legend><div class="appearance-colors">${SQUAD_COLORS.map(([color,label])=>`<button type="button" class="appearance-choice ${appearance.color===color?'selected':''}" data-squad-color="${color}" style="--choice-color:${color}" aria-label="${label}" aria-pressed="${appearance.color===color}" title="${label}"><span></span></button>`).join('')}</div></fieldset></div><div class="slot-editor-heading"><span>Postes de l’escouade</span><span id="slot-count"></span></div><div id="slot-editor"></div><button type="button" class="btn ghost" id="add-slot">${icon('plus')}Ajouter une place</button><p class="slot-editor-hint">${q?'Les places occupées restent attribuées à leurs membres.':'Ta place est incluse. Tu seras le chef de cette escouade.'} Choisis « Autre » pour un poste personnalisé.</p>`,q?'Enregistrer':'Créer l’escouade',async data=>{
   if(slots.some(t=>!t.role.trim()))throw new Error('Renseigne le nom de chaque poste personnalisé.');
   const cleanSlots=slots.map(t=>({...t,role:t.role.trim()}));
   const action={type:q?'edit':'create',squadId:q?.id,name:data.get('name'),kind:data.get('kind'),mood:data.get('mood'),...appearance};
   if(q)action.slots=cleanSlots;else{action.role=cleanSlots[0].role;action.roles=cleanSlots.slice(1).map(t=>t.role);}
   await dispatch(action,q?'Escouade mise à jour.':'Escouade créée. Tu en es le chef.');if(!q)nav(channelExperiment&&shared?'operations':'mine');
 });
 for(const el of modal.querySelectorAll('[data-squad-icon],[data-squad-color]'))el.onclick=()=>{
   const kind=el.dataset.squadIcon?'icon':'color';appearance[kind]=el.dataset.squadIcon||el.dataset.squadColor;
   for(const choice of el.parentElement.children){const active=choice===el;choice.classList.toggle('selected',active);choice.setAttribute('aria-pressed',active);}
 };
 const drawSlots=(focusId,customFocus=false)=>{
   $('#slot-editor').innerHTML=slots.map((t,i)=>{
     const custom=customSlots.has(t.id);
     const occupant=t.playerId?player(t.playerId):null;
     const isLeader=t.playerId&&(q?q.leaderId===t.playerId:t.playerId===state.currentUserId);
     return `<div class="slot-editor"><div class="slot-role-controls"><select aria-label="Poste ${i+1}" data-role-select="${escape(t.id)}">${optionList(PREDEFINED_ROLES,custom?CUSTOM_ROLE:t.role)}<option value="${CUSTOM_ROLE}" ${custom?'selected':''}>Autre</option></select>${custom?`<input aria-label="Poste personnalisé ${i+1}" maxlength="32" required placeholder="Nom du poste" value="${escape(t.role)}" data-slot-role="${escape(t.id)}">`:''}</div><small title="${escape(occupant?.name||'Place libre')}">${occupant?escape(occupant.name)+(isLeader?' · Chef':''):'Place libre'}</small>${!t.playerId?`<button type="button" aria-label="Supprimer la place ${i+1}" data-remove-slot="${escape(t.id)}">${icon('close')}</button>`:'<span class="slot-remove-spacer"></span>'}</div>`;
   }).join('');
   $('#slot-count').textContent=slots.length+' / 16';$('#add-slot').disabled=slots.length>=16;
   if(focusId)$('#slot-editor').querySelector(`[${customFocus?'data-slot-role':'data-role-select'}="${CSS.escape(focusId)}"]`)?.focus();
 };
 $('#slot-editor').addEventListener('change',e=>{
   const id=e.target.dataset.roleSelect;if(!id)return;
   const slot=slots.find(t=>t.id===id),value=e.target.value;
   if(value===CUSTOM_ROLE){customSlots.add(id);slot.role=customValues.get(id)||'';}
   else{customSlots.delete(id);slot.role=value;}
   drawSlots(id,value===CUSTOM_ROLE);
 });
 $('#slot-editor').addEventListener('input',e=>{const id=e.target.dataset.slotRole;if(id){slots.find(t=>t.id===id).role=e.target.value;customValues.set(id,e.target.value);}});
 $('#slot-editor').addEventListener('click',e=>{
   const b=e.target.closest('[data-remove-slot]');if(!b)return;
   const id=b.dataset.removeSlot,index=slots.findIndex(t=>t.id===id);
   if(slots[index]?.playerId)return;
   slots=slots.filter(t=>t.id!==id);customSlots.delete(id);customValues.delete(id);
   drawSlots(slots[Math.min(index,slots.length-1)]?.id);
 });
 $('#add-slot').onclick=()=>{if(slots.length>=16)return;const slot={id:uid(),role:'Infanterie',playerId:null};slots.push(slot);drawSlots(slot.id);};
 drawSlots();
}
function manageMember(q,id){ const p=player(id);showDialog('Gérer '+p.name,`<p class="dialog-description">${escape(q.name)} · ${escape(q.slots.find(t=>t.playerId===id).role)}</p><label class="field" style="margin-top:20px"><span>Action</span><select name="operation">${q.leaderId!==id?`<option value="leader">Transférer le commandement</option><option value="deputy">${q.deputyId===id?'Retirer le rôle adjoint':'Nommer adjoint'}</option><option value="remove">Retirer de l’escouade</option>`:'<option value="none">Chef actuel — choisis un autre membre pour transférer</option>'}</select></label><p class="subtext">Le transfert est immédiat. Le poste occupé reste le même.</p>`,'Appliquer',async data=>{const type=data.get('operation');if(type==='none')return;await dispatch({type,squadId:q.id,playerId:type==='deputy'&&q.deputyId===id?null:id},'Composition mise à jour.');});}
async function exportState(){if(window.desktop){if(await window.desktop.export(state))toast('Sauvegarde exportée.');}else{const blob=new Blob([JSON.stringify(state,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='umbra-escouades.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}}
async function importState(){
 if(!window.desktop)return toast('Import disponible dans l’application Windows.',true);
 const imported=await window.desktop.import();if(!imported)return;validateState(imported);
 confirmDialog('Remplacer la composition ?',`Cette sauvegarde contient ${imported.squads.length} escouade(s) et ${imported.players.length} joueur(s). Elle remplacera les données locales actuelles. Exporte-les d’abord si tu souhaites les conserver.`,'Importer',async()=>{state=await persist(imported);loadError=null;render();toast('Sauvegarde importée.');});
}
function stopMic(){
 if(micMonitor){micMonitor.pause();micMonitor.srcObject=null;micMonitor.remove();micMonitor=null;}if(voice.monitoring){voice.monitoring=false;voice.applyTransmit();}
 if(frameId)clearInterval(frameId);frameId=null;if(stream)stream.getTracks().forEach(t=>t.stop());stream=null;micMode=null;
 micGraph?.stream.getTracks().forEach(t=>t.stop());micGraph=null;if(audioContext)audioContext.close().catch(()=>{});audioContext=null;
 document.querySelectorAll('.speech-ring').forEach(el=>{el.classList.remove('is-speaking');el.setAttribute('aria-label','Activité vocale indisponible');});
}
async function toggleMic(mode='test'){
 if(micStarting)return;
 if(stream&&micMode===mode){stopMic();render();return;}
 stopMic();micStarting=true;
 if($('#mic-status'))$('#mic-status').textContent='Ouverture du microphone…';
 const accountId=state?.currentUserId;
 try{
  const mic=state.settings.mic;stream=await navigator.mediaDevices.getUserMedia({audio:{deviceId:mic?{exact:mic}:undefined,...captureOptions(state.settings)},video:false});
  if(!state||state.currentUserId!==accountId||mode==='test'&&page!=='settings'){stopMic();return;}
  micMode=mode;
  await refreshAudioDevices();
  micGraph=await microphoneGraph(stream,state.settings.inputVolume);audioContext=micGraph.context;const analyser=micGraph.analyser;
  if(mode==='test'){voice.monitoring=true;await voice.applyTransmit();micMonitor=document.createElement('audio');micMonitor.dataset.micMonitor='true';micMonitor.srcObject=micGraph.stream;micMonitor.volume=state.settings.outputVolume/100;if(state.settings.output&&micMonitor.setSinkId)await micMonitor.setSinkId(state.settings.output);document.body.append(micMonitor);await micMonitor.play();}
  const samples=new Float32Array(analyser.fftSize),isVoice=createVoiceGate();render();
  const tick=()=>{
   if(!stream)return;analyser.getFloatTimeDomainData(samples);const rms=rmsLevel(samples),active=isVoice(rms,performance.now(),thresholdAmplitude(gatePreview??state.settings.vadThresholdDb));
   if(!shared)document.querySelectorAll(`[data-speaker="${CSS.escape(accountId)}"]`).forEach(el=>{el.classList.toggle('is-speaking',active);el.setAttribute('aria-label',active?'Voix détectée au microphone local':'Microphone local silencieux');});
   updateMicMeter(rms,state.settings,gatePreview);
  };tick();frameId=setInterval(tick,50);
 }catch(error){
  stopMic();render();const msg=error.name==='NotAllowedError'?'Accès au microphone refusé. Autorise les applications de bureau dans les réglages microphone de Windows.':error.name==='NotFoundError'?'Aucun microphone détecté. Branche un micro puis réessaie.':error.name==='OverconstrainedError'?'Ce microphone n’est plus disponible. Sélectionne celui par défaut.':'Impossible d’ouvrir le microphone : '+error.message;
  if($('#mic-status'))$('#mic-status').textContent=msg;toast(msg,true);
 }finally{micStarting=false;}
}

document.addEventListener('click',async e=>{
 const target=e.target.closest('[data-nav],[data-action],[data-chat-select],[data-chat-create],[data-chat-delete]');if(!target)return;
 if($('#tour') && !['close','minimize','maximize'].includes(target.dataset.action))return;
  if(target.dataset.chatSelect){openTextChannel(target.dataset.chatSelect);return;}
  if(target.hasAttribute('data-chat-create')){createTextChannel();return;}
  if(target.dataset.chatDelete){deleteTextChannel(target.dataset.chatDelete);return;}
  if(target.dataset.nav){if(target.dataset.nav==='operations')roomMode='voice';nav(target.dataset.nav);return;}
 const action=target.dataset.action,id=target.dataset.id;
 try{
  if(['minimize','maximize','close'].includes(action)){window.desktop?.[action]();return;}
  if(['mine','operations'].includes(action)){if(action==='operations')roomMode='voice';nav(action);return;}
  if(action==='dismiss'){modal.close();return;}
  if(action==='tutorial'){startTour();return;}
  if(action==='logout'){await voice.disconnect();stopMic();remoteSpeaking.clear();remoteVoiceStates.clear();voiceUsers=[];await window.desktop.logout();state=null;channelsView.reset();roomMode='voice';document.body.classList.remove('channel-layout');railWasVisible=false;page='operations';query='';filter='all';await start();return;}
  if(action==='auth-mode'){authMode=authMode==='register'?'login':authMode==='reset'?'login':'register';renderAuth();return;}
  if(action==='show-password'){const input=$('#auth-password');input.type=input.type==='password'?'text':'password';target.textContent=input.type==='password'?'Afficher':'Masquer';return;}
  if(action==='detail'){selected=id;roomMode='voice';nav('detail');return;}
  if(action==='create'){squadForm();return;}
  if(action==='edit'){squadForm(squad(id));return;}
  if(action==='profile'){profileForm();return;}
  if(action==='viewProfile'){viewProfile(target.dataset.player);return;}
  if(action==='createOperation'){operationForm();return;}
  if(action==='editOperation'){operationForm(state.operations.find(o=>o.id===id));return;}
  if(action==='joinOperation'||action==='leaveOperation'||action==='briefing'){
    const mine=membership(state);
   if(!mine)throw new Error('Crée ou rejoins une escouade d’abord.');
    const o=state.operations.find(o=>o.id===id);
    const type=action==='joinOperation'?'operationJoin':action==='leaveOperation'?'operationLeave':o.briefingSquadIds.includes(mine.id)?'briefingLeave':'briefingJoin';
    await dispatch({type,operationId:id,squadId:mine.id},type==='briefingJoin'?shared?'Squad rassemblée : les clients connectés rejoignent le briefing.':'Squad attendue au briefing. Le vocal partagé nécessite le serveur.':type==='briefingLeave'?'Squad retirée de la préparation du briefing.':'Inscription de la squad mise à jour.');return;
  }
  if(action==='deleteOperation'){confirmDialog('Supprimer cette opération ?','Les escouades et leurs membres sont conservés. Leur inscription et la préparation du briefing seront retirées.','Supprimer',()=>dispatch({type:'operationDelete',operationId:id},'Opération supprimée.'));return;}
  if(action==='serverSettings'){configureServerDialog();return;}
  if(action==='invitation'){const result=await window.desktop.invitation();showDialog('Inviter la team',`<p class="dialog-description">Partage ce code avec les joueurs pour créer leur compte sur ce serveur.</p><label class="field"><span>Code de la team</span><input readonly value="${escape(result.joinCode)}"></label>`,null,()=>{});return;}
  if(action==='voiceConnect'){if(voice.enabled)await voice.disconnect();else await connectHome();render();return;}
  if(action==='voiceSquad'){if(membership(state)?.id!==id)throw new Error('Rejoins d’abord cette escouade.');await connectHome();render();return;}
  if(action==='voiceLobby'){if(membership(state))throw new Error('L’accueil est réservé aux joueurs sans escouade.');await connectHome();render();return;}
  if(action==='voiceMute'){voice.setMute(!voice.muted);return;}
  if(action==='voiceDeafen'){voice.setDeafen(!voice.deafened);return;}
  if(action==='voiceAudio'){await voice.startAudio();return;}
  if(action==='voiceVisit'){await window.desktop.visitVoice(id);if(!voice.enabled){stopMic();await voice.connect(state.settings);}else await voice.sync(state.settings);render();return;}
  if(action==='voiceHome'){await window.desktop.visitVoice(null);if(voice.enabled)await voice.sync(state.settings);render();return;}
  if(action==='activity'){await toggleMic('activity');return;}
  if(action==='join'){await dispatch({type:'join',squadId:id,slotId:target.dataset.slot},'Tu as rejoint l’escouade.');return;}
  if(action==='leave'){confirmDialog('Quitter l’escouade ?','Ta place sera libérée. Si tu es chef, transfère d’abord le commandement à un autre membre.','Quitter',()=>dispatch({type:'leave',squadId:id},'Tu as quitté l’escouade.'));return;}
  if(action==='delete'){confirmDialog('Dissoudre cette escouade ?',`L’escouade ${squad(id).name} sera supprimée et tous ses membres redeviendront disponibles.`,'Dissoudre',async()=>{await dispatch({type:'delete',squadId:id},'Escouade dissoute.');nav('operations');});return;}
  if(action==='assign'){const free=state.players.filter(p=>!membership(state,p.id));if(!free.length)return toast('Tous les joueurs ont déjà une escouade.',true);showDialog('Affecter un joueur',`<label class="field"><span>Joueur disponible</span><select name="player">${free.map(p=>`<option value="${escape(p.id)}">${escape(p.name)}</option>`).join('')}</select><small>Affectation locale : aucune invitation réseau n’est envoyée.</small></label>`,'Affecter',data=>dispatch({type:'assign',squadId:id,slotId:target.dataset.slot,playerId:data.get('player')},'Joueur affecté.'));return;}
  if(action==='member'){manageMember(squad(id),target.dataset.player);return;}
  if(action==='messageReaction'){await channelsView.react(target.dataset.message,target.dataset.emoji);modal.close();return;}
  if(action==='messagePins'){await showPinnedMessages();return;}
  if(action==='jumpPin'){modal.close();await channelsView.jumpTo(target.dataset.message);return;}
  if(action==='copyValue'){await window.desktop.copyText(target.dataset.copyValue);toast('Copié.');return;}
  if(action==='passwordResetCode'){if(!me().admin)return;const p=player(target.dataset.player);confirmDialog('Réinitialiser le mot de passe de '+p.name+' ?', 'Un code valable 30 minutes permettra au joueur de choisir un nouveau mot de passe.','Créer le code',async()=>{const value=await window.desktop.passwordResetCode(p.id);setTimeout(()=>showDialog('Code pour '+value.name,`<p class="dialog-description">Transmets ce code au joueur. Il devra cliquer sur « Mot de passe oublié ? » à la connexion. Usage unique, valable 30 minutes.</p><label class="field"><span>Code de récupération</span><input readonly value="${escape(value.code)}" aria-label="Code de récupération"></label>${button('Copier le code','copyValue',`data-copy-value="${escape(value.code)}"`,'gold')}`,null,()=>{}),0);});return;}
  if(action==='forgotPassword'){authMode='reset';renderAuth();return;}
  if(action==='rights'){if(!me().admin)return;const p=player(target.dataset.player);showDialog('Permissions de '+p.name,`<p class="dialog-description">Les grades sont attribués par les admins. Le chef actuel d’une escouade dépend de sa composition.</p><label class="check"><input type="checkbox" name="admin" ${p.admin?'checked':''}>Admin · gérer les escouades et les effectifs</label><label class="check"><input type="checkbox" name="squadLeader" ${p.squadLeader?'checked':''}>Squad leader · grade permanent</label><label class="check"><input type="checkbox" name="commander" ${p.commander?'checked':''}>Commandant · réseau leaders et annonces générales</label>`,'Enregistrer',data=>dispatch({type:'rights',playerId:p.id,admin:data.has('admin'),commander:data.has('commander'),squadLeader:data.has('squadLeader')},'Permissions enregistrées.'));return;}
  if(action==='audio'){settingsTab='voice';nav('settings');return;}
  if(action==='settingsTab'){if(micMode==='test')stopMic();settingsTab=target.dataset.tab;render();$('.content-scroll').scrollTop=0;if(settingsTab==='voice')refreshAudioDevices();return;}
  if(action==='shortcut'){await shortcutForm(target.dataset.kind);return;}
  if(action==='chooseSlot'){chooseSlot(squad(id));return;}
  if(action==='audioDevices'){await refreshAudioDevices();return;}
  if(action==='updateNow'){const result=updateState.phase==='ready'?updateState:await window.desktop.updatesCheck();if(result.phase==='ready'){await voice.disconnect();stopMic();await window.desktop.updatesInstall();}return;}
  if(action==='updatesCheck'){await window.desktop.updatesCheck();return;}
  if(action==='updatesInstall'){await voice.disconnect();stopMic();await window.desktop.updatesInstall();return;}
  if(action==='soundTest'){voice.sounds.configure(state.settings,voice.deafened);await voice.sounds.play('join');if(voice.sounds.error)toast(voice.sounds.error,true);return;}
  if(action==='mic'){await toggleMic('test');return;}
  if(action==='export'){await exportState();return;}
  if(action==='import'){await importState();return;}
 }catch(error){toast(friendlyError(error),true);}
});
document.addEventListener('input',e=>{if(e.target.id==='search'){query=e.target.value;$('#squad-results').innerHTML=cards();}if(e.target.dataset.setting==='vadThresholdDb'){gatePreview=Number(e.target.value);voice.vadPreview=gatePreview;for(const range of document.querySelectorAll('[data-setting=vadThresholdDb]'))if(range!==e.target)range.value=gatePreview;const out=$('[data-vad-threshold]');if(out)out.textContent=e.target.value+' dB';const marker=$('#mic-threshold');if(marker)marker.style.left=meterPercent(Number(e.target.value))+'%';}if(e.target.dataset.setting){const volume=document.querySelector('[data-volume-for="'+CSS.escape(e.target.dataset.setting)+'"]');if(volume)volume.textContent=e.target.value+' %';const out=e.target.dataset.setting==='squadVolume'?'#squad-output':'#leaders-output';if($(out))$(out).textContent=e.target.value+'%';}});
document.addEventListener('change',async e=>{try{if(e.target.id==='channel-experiment'){channelExperiment=e.target.checked;localStorage.setItem('umbra-channel-experiment',channelExperiment?'on':'off');if(!channelExperiment){roomMode='voice';channelsView.reset();}render();if(channelExperiment&&shared)channelsView.refresh(state);return;}if(e.target.hasAttribute('data-voice-mode')){await voice.configure({mode:e.target.value});render();return;}if(e.target.id==='audio-profile'){const value=e.target.value,presets={standard:{noiseSuppression:true,echoCancellation:true,autoGainControl:false},studio:{noiseSuppression:false,echoCancellation:false,autoGainControl:false},custom:{}};await dispatch({type:'settings',values:{audioProfile:value,...presets[value]}});if(stream)await stream.getAudioTracks()[0].applyConstraints(captureOptions(state.settings));return;}if(e.target.dataset.audioToggle){await dispatch({type:'settings',values:{[e.target.dataset.audioToggle]:e.target.checked,audioProfile:'custom'}});if(stream)await stream.getAudioTracks()[0].applyConstraints(captureOptions(state.settings));return;}if(e.target.id==='filter'){filter=e.target.value;$('#squad-results').innerHTML=cards();}if(e.target.dataset.setting){const focusGate=e.target.id==='gate-on-meter'&&document.activeElement===e.target;if(e.target.dataset.setting==='vadThresholdDb'){gatePreview=null;voice.vadPreview=null;}if(micGraph&&e.target.dataset.setting==='inputVolume')micGraph.gain.gain.value=Number(e.target.value)/100;await dispatch({type:'settings',values:{[e.target.dataset.setting]:Number(e.target.value)}});if(focusGate)$('#gate-on-meter')?.focus({preventScroll:true});}if(e.target.id==='ducking')await dispatch({type:'settings',values:{ducking:e.target.checked}});if(e.target.id==='mic-select'){stopMic();await dispatch({type:'settings',values:{mic:e.target.value}});}if(e.target.id==='output-select')await dispatch({type:'settings',values:{output:e.target.value}});if(e.target.id==='notification-sounds')await dispatch({type:'settings',values:{notificationSounds:e.target.checked}});}catch(error){toast(friendlyError(error),true);}});
window.addEventListener('pagehide',stopMic);
let authMode='register';
function renderAuth(error=''){playerMenu.close();channelMenu.close();messageMenu.close();if(authMode==='reset')return renderRecovery(error);
 $('#app').innerHTML=`${titlebar()}<main class="auth-shell"><section class="auth-intro"><div class="brand">${brand}<div><div class="brand-name">UMBRA</div><div class="brand-sub">WARDOGS COMPANION</div></div></div><div class="auth-message"><span class="eyebrow">Votre espace d’équipe</span><h1>Une équipe.<br>Un seul endroit.</h1><p>Crée ton escouade, choisis ton poste<br>et prépare ta prochaine partie.</p><div class="auth-line"></div><span class="auth-version">${escape(appVersion)} / WINDOWS</span></div></section><section class="auth-right"><div class="auth-top-info"><span data-top-update class="top-update-slot"></span><span class="build-label">P.H.A.N.T.O.M</span></div><form id="auth-form" class="auth-form"><div class="eyebrow">${authMode==='register'?'Première connexion':'Bon retour'}</div><h2>${authMode==='register'?'Créer un compte':'Se connecter'}</h2><p class="auth-subtitle">${authMode==='register'?'Un pseudo, un mot de passe. C’est tout.':'Retrouve tes escouades et tes réglages.'}</p><label class="field"><span>Pseudo</span><input id="auth-name" name="name" autocomplete="username" required minlength="2" maxlength="32" placeholder="Ton pseudo" value="${escape(authMode==='login'?localStorage.getItem('umbra-last-name')||'':'')}"></label><label class="field"><span>Mot de passe</span><div class="password-field"><input id="auth-password" name="password" type="password" autocomplete="${authMode==='register'?'new-password':'current-password'}" required ${authMode==='register'?'minlength="8"':''} maxlength="128" placeholder="${authMode==='register'?'8 caractères minimum':'Ton mot de passe'}"><button type="button" data-action="show-password">Afficher</button></div></label>${shared&&authMode==='register'?`<label class="field"><span>Code de la team</span><input name="joinCode" required autocomplete="off" placeholder="Code fourni par un admin"></label>`:''}<label class="check auth-remember"><input type="checkbox" name="remember" id="auth-remember">Rester connecté</label><p class="error-text" id="auth-error" role="alert">${escape(error)}</p><button class="btn gold block auth-submit" type="submit">${authMode==='register'?'Créer mon compte':'Se connecter'} ${icon('arrow')}</button>${authMode==='login'?'<button type="button" class="auth-forgot" data-action="forgotPassword">Mot de passe oublié ?</button>':''}<p class="auth-switch">${authMode==='register'?'Déjà un compte ?':'Pas encore de compte ?'} <button type="button" data-action="auth-mode">${authMode==='register'?'Se connecter':'Créer un compte'}</button></p><p class="auth-local">${shared?'Compte partagé sur le serveur de la team.<br>Le vocal se rejoint après la connexion.':'Mode hors ligne : compte enregistré sur ce PC.'}<br><button type="button" class="server-link" data-action="serverSettings">${shared?escape(serverAddress):'Choisir le serveur de la team'}</button></p></form></section></main>`;
 $('#auth-form').onsubmit=async e=>{
  e.preventDefault();const button=e.target.querySelector('[type=submit]');button.disabled=true;$('#auth-error').textContent='';
  try{const data=new FormData(e.target);const result=await window.desktop[authMode]({name:data.get('name'),password:data.get('password'),joinCode:data.get('joinCode'),remember:data.get('remember')==='on'});$('#auth-password').value='';acceptSession(result);}
  catch(error){$('#auth-error').textContent=friendlyError(error);button.disabled=false;}
 };
}
function acceptSession(result){remoteVoiceStates=new Map((result.voiceStates||[]).map(v=>[v.userId,v]));voiceUsers=result.voiceUsers||[];onlineIds=result.onlineIds||[];state=result.state;localStorage.setItem('umbra-last-name',me().name);render();if(channelExperiment&&shared)channelsView.refresh(state);if(!result.tutorialSeen)startTour();}
function renderRecovery(error=''){
 $('#app').innerHTML=`${titlebar()}<main class="recovery-layout"><form id="reset-form" class="auth-form"><div class="eyebrow">Récupération du compte</div><h2>Nouveau mot de passe</h2><p class="auth-subtitle">Demande un code temporaire à un admin de P.H.A.N.T.O.M.</p><label class="field"><span>Pseudo</span><input name="name" required autocomplete="username" maxlength="32" value="${escape(localStorage.getItem('umbra-last-name')||'')}"></label><label class="field"><span>Code fourni par l’admin</span><input name="code" required maxlength="100" autocomplete="off"></label><label class="field"><span>Nouveau mot de passe</span><input name="password" type="password" required minlength="8" maxlength="128" autocomplete="new-password"></label><label class="field"><span>Confirmer le mot de passe</span><input name="confirm" type="password" required minlength="8" maxlength="128" autocomplete="new-password"></label><p class="error-text" role="alert" id="reset-error">${escape(error)}</p><button type="submit" class="btn gold block">Enregistrer le mot de passe</button><p class="auth-switch"><button type="button" data-action="auth-mode">Retour à la connexion</button></p></form></main>`;
 $('#reset-form').onsubmit=async e=>{e.preventDefault();const submit=e.target.querySelector('[type=submit]');submit.disabled=true;try{const data=new FormData(e.target);if(data.get('password')!==data.get('confirm'))throw new Error('Les deux mots de passe doivent être identiques.');await window.desktop.resetPassword({name:data.get('name'),code:data.get('code'),password:data.get('password')});localStorage.setItem('umbra-last-name',data.get('name').trim());authMode='login';renderAuth();toast('Mot de passe réinitialisé. Connecte-toi avec le nouveau.');}catch(error){$('#reset-error').textContent=friendlyError(error);submit.disabled=false;}};
}
const tourSteps=[
 {page:'operations',target:'[data-nav="operations"]',title:'Escouades et briefing.',text:'Ici, tu retrouves les équipes créées. Clique sur « Créer une escouade » pour choisir son nom et ses postes. Les places libres se rejoignent depuis sa fiche. Le bouton « Créer une opération » définit le serveur et l’horaire. Les squads inscrites apparaissent sous leur salle de briefing.'},
 {page:'mine',target:'[data-nav="mine"]',title:'Ta squad, en un clic.',text:'Retrouve ta composition et ton poste dans « Mon escouade ». Le chef peut modifier les places, nommer un adjoint ou transmettre le commandement.'},
 {page:'players',target:'[data-nav="players"]',title:'Les personnes, pas des exemples.',text:'« Membres » affiche uniquement les comptes créés ici. Les responsabilités de chef, commandant et admin sont distinctes. Aucun profil fictif n’est ajouté.'},
 {page:'settings',target:'[data-nav="settings"]',title:'Un dernier réglage avant de jouer.',text:'Choisis ton micro, ton casque, tes volumes et le mode de transmission de la squad ici. Rejoins ensuite le vocal depuis la barre latérale. Tu peux revoir ce guide depuis la barre latérale.'}
];
let tourIndex=0;
function startTour(){stopMic();if(modal.open)modal.close();tourIndex=0;drawTour();}
function drawTour(){
 $('#tour')?.remove();document.querySelectorAll('.tour-highlight').forEach(el=>el.classList.remove('tour-highlight'));
 const steps=tourSteps.filter(s=>s.page!=='players'||me().admin),step=steps[tourIndex];nav(step.page);const target=$(step.target);target.classList.add('tour-highlight');
 const overlay=document.createElement('div');overlay.id='tour';overlay.innerHTML=`<div class="tour-shade"></div><section class="tour-card" role="dialog" aria-modal="true" aria-labelledby="tour-title"><div class="tour-top"><span>GUIDE RAPIDE · ${tourIndex+1} / ${steps.length}</span><button id="tour-skip">Passer</button></div><h2 id="tour-title">${step.title}</h2><p>${step.text}</p><div class="tour-bottom"><div class="tour-dots">${steps.map((_,i)=>`<span class="${i===tourIndex?'active':''}"></span>`).join('')}</div><div>${tourIndex?'<button class="btn ghost" id="tour-prev">Retour</button>':''}<button class="btn gold" id="tour-next">${tourIndex===steps.length-1?'C’est parti':'Suivant'} ${icon('arrow')}</button></div></div><p class="error-text" id="tour-error" role="alert"></p></section>`;document.body.append(overlay);
 const finish=async()=>{try{await window.desktop.tutorialDone();overlay.remove();nav('operations');}catch(e){$('#tour-error').textContent=friendlyError(e);}};
 $('#tour-skip').onclick=finish;$('#tour-next').onclick=()=>{if(tourIndex===steps.length-1)finish();else{tourIndex++;drawTour();}};if($('#tour-prev'))$('#tour-prev').onclick=()=>{tourIndex--;drawTour();};
 $('#tour-next').focus();
 overlay.onkeydown=e=>{if(e.key==='Escape'){e.preventDefault();finish();}if(e.key==='Tab'){const buttons=[...overlay.querySelectorAll('button')];const first=buttons[0],last=buttons.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}}};
}
function updateVoiceUI(){
 if(!state)return;
 const self=state.currentUserId;
 for(const el of document.querySelectorAll('[data-rail-squad]')){const html=railVoicePeople(el.dataset.railSquad);if(el.dataset.roster!==html){el.dataset.roster=html;el.innerHTML=html;}}
 for(const el of document.querySelectorAll('[data-operation-presence]'))el.textContent=voiceUsers.filter(p=>p.channels.some(c=>c.kind==='primary'&&c.operationId===el.dataset.operationPresence)).length+' en vocal';
 for(const el of document.querySelectorAll('[data-squad-guests]')){const q=squad(el.dataset.squadGuests);if(q){const html=voiceVisitors(q);if(el.dataset.roster!==html){el.dataset.roster=html;el.innerHTML=html;}}}
  const lobbyList=$('[data-lobby-members]');if(lobbyList){const html=lobbyMembers();if(lobbyList.dataset.roster!==html){lobbyList.dataset.roster=html;lobbyList.innerHTML=html;}}
 for(const el of document.querySelectorAll('[data-speaker]')){
  const id=el.dataset.speaker,local=id===self,flags=local?{connected:voice.enabled,muted:voice.muted,deafened:voice.deafened}:remoteVoiceStates.get(id),present=local||voiceUsers.some(p=>p.id===id),active=local?voice.enabled&&voice.speaking:networkOnline&&remoteSpeaking.get(id)?.speaking===true;
  const indicator=voiceIndicator(present?flags:{},active),muted=indicator==='muted'||indicator==='deafened';
  if(el.dataset.voiceState!==indicator){el.dataset.voiceState=indicator;el.classList.toggle('is-muted',indicator==='muted');el.classList.toggle('is-deafened',indicator==='deafened');const badge=el.querySelector('.voice-mute-badge');if(badge)badge.innerHTML=muted?icon(indicator==='deafened'?'headset':'mic').replace('</svg>','<path d="M3 3 21 21"/></svg>'):'';}
  if(shared||voice.enabled||muted)el.classList.toggle('is-speaking',indicator==='speaking');
  const label=indicator==='deafened'?'Casque et microphone coupés':indicator==='muted'?'Microphone coupé':indicator==='speaking'?'En train de parler':'Microphone au repos';el.title=label;el.setAttribute('aria-label',label);el.setAttribute('role','img');
 }
 for(const connect of document.querySelectorAll('[data-action=voiceConnect]')){if(!connect.dataset.iconOnly)connect.textContent=voice.connecting?'Connexion…':voice.enabled?'Quitter le vocal':membership(state)?'Rejoindre '+membership(state).name:'Rejoindre l’accueil';connect.disabled=voice.connecting;}
 for(const el of document.querySelectorAll('[data-voice-label]'))el.textContent=voice.connecting?'Connexion…':voice.enabled?voice.label:membership(state)?.name||'Accueil vocal';
 for(const b of document.querySelectorAll('[data-ptt]')){b.classList.toggle('radio-transmitting',voice.transmitting===b.dataset.ptt);b.disabled=!voice.enabled||voice.connecting||b.dataset.pttAllowed==='0';b.textContent=b.dataset.ptt==='primary'&&voice.mode==='vad'?'Détection de voix · '+voice.keyLabel('primary')+' pour forcer':'Maintenir '+voice.keyLabel(b.dataset.ptt)+' pour parler';}
 for(const mute of document.querySelectorAll('[data-action=voiceMute]')){const muted=voice.muted||voice.deafened;mute.classList.toggle('radio-muted',muted);mute.classList.toggle('icon-struck',muted);mute.setAttribute('aria-pressed',muted);mute.setAttribute('aria-label',voice.muted?'Réactiver mon micro':'Couper mon micro');mute.title=voice.deafened?'Micro coupé avec le casque':voice.muted?'Réactiver mon micro':'Couper mon micro';}
 for(const deafen of document.querySelectorAll('[data-action=voiceDeafen]')){deafen.classList.toggle('radio-muted',voice.deafened);deafen.classList.toggle('icon-struck',voice.deafened);deafen.setAttribute('aria-pressed',voice.deafened);deafen.setAttribute('aria-label',voice.deafened?'Réactiver le casque':'Couper le son');deafen.title=voice.deafened?'Réactiver le casque':'Couper le son';}
  updateVoiceDock();
 const notice=$('[data-voice-error]');if(notice)notice.textContent=voice.error;
}
function voiceVisitors(q){
 if(!shared)return '';
 const members=new Set(q.slots.map(t=>t.playerId));
 const guests=voiceUsers.filter(v=>!members.has(v.id)&&v.channels.some(c=>c.kind==='primary'&&c.squadId===q.id)).map(v=>player(v.id)).filter(Boolean);
 return guests.map(p=>`<tr class="voice-guest-row"><td><div class="member" data-player="${escape(p.id)}">${speaking(p.id)}<button class="name-link" data-action="viewProfile" data-player="${escape(p.id)}">${displayName(p)}</button></div></td><td><span class="subtext">Admin · en vocal</span></td><td><span class="subtext">Hors effectif</span></td></tr>`).join('');
}
async function connectHome(){
 if(me().admin)await window.desktop.visitVoice(null);
 stopMic();if(voice.enabled)await voice.sync(state.settings);else await voice.connect(state.settings);
}
function configureServerDialog(){
 showDialog('Connexion à la team',`<label class="field"><span>Adresse du serveur UMBRA</span><input name="server" type="url" value="${escape(serverAddress||'https://lotus-order.fr/umbra-api')}" required placeholder="https://…"><small>Les comptes, escouades et opérations de ce serveur sont partagés entre les joueurs.</small></label><button class="btn ghost" type="button" id="use-offline">Continuer hors ligne sur ce PC</button>`,'Se connecter',async data=>{await voice.disconnect();stopMic();const info=await window.desktop.configureServer(data.get('server'));shared=info.shared;serverAddress=info.url;state=null;await start();});
 $('#use-offline').onclick=async()=>{try{await voice.disconnect();stopMic();const info=await window.desktop.configureServer('');shared=false;serverAddress='';state=null;modal.close();await start();}catch(e){$('#dialog-error').textContent=friendlyError(e);}};
}
function networkPanel(){return `<div class="panel"><div class="panel-heading">Serveur de la team</div><div class="panel-body"><p class="settings-note">${shared?escape(serverAddress):'Mode hors ligne · données sur ce PC'}</p>${button('Changer de serveur','serverSettings')}${shared&&me().admin?button('Code de la team','invitation','','ghost'):''}</div></div>`;}

function deviceOptions(devices,selected,label){
 return `<option value="">${label} par défaut de Windows</option>${selected&&!devices.some(d=>d.deviceId===selected)?`<option value="${escape(selected)}" selected>Périphérique enregistré · indisponible</option>`:''}${devices.map(d=>`<option value="${escape(d.deviceId)}" ${selected===d.deviceId?'selected':''}>${escape(d.label)}</option>`).join('')}`;
}
function volumeField(key,label,max=100){const value=state.settings[key];return `<label class="field volume-field"><span>${label}<output data-volume-for="${key}">${value} %</output></span><input type="range" min="0" max="${max}" value="${value}" data-setting="${key}" aria-label="${label}"></label>`;}
function audioPanel(){return `<section class="panel audio-settings"><div class="panel-heading">Voix</div><div class="panel-body"><div class="audio-columns"><div><label class="field"><span>${icon('mic')}Microphone</span><select id="mic-select">${deviceOptions(micDevices,state.settings.mic,'Microphone')}</select></label>${volumeField('inputVolume','Volume du micro',200)}</div><div><label class="field"><span>${icon('headset')}Haut-parleurs / casque</span><select id="output-select">${deviceOptions(outputDevices,state.settings.output,'Sortie audio')}</select></label>${volumeField('outputVolume','Volume des haut-parleurs')}</div></div><div class="mic-test-row">${button(stream&&micMode==='test'?'Arrêter le test':'Test du micro','mic','','gold')}<div class="microphone-meter" data-gate-bar role="meter" aria-label="Niveau du microphone" aria-valuemin="0" aria-valuemax="100" aria-valuenow="0"><span id="mic-level"></span><input type="range" id="gate-on-meter" class="gate-on-meter" min="-65" max="-20" step="1" value="${state.settings.vadThresholdDb}" data-setting="vadThresholdDb" aria-label="Gate sur la jauge" title="Cliquer ou glisser pour régler le seuil"><i id="mic-threshold" style="left:${meterPercent(state.settings.vadThresholdDb)}%" aria-hidden="true"></i></div></div><p class="subtext vad-live-level" data-vad-level>Parle normalement pour vérifier la détection.</p><p id="mic-status" class="subtext">${stream?micMode==='activity'?'Détection locale active · aucun son transmis':'Test actif · retour audio dans ta sortie sélectionnée':voice.enabled?'Niveau du microphone en vocal':'Microphone arrêté'}</p><div class="audio-device-actions">${button('Actualiser les périphériques','audioDevices','','ghost')}<span id="audio-device-status" class="subtext">${deviceLoading?'Recherche…':''}</span></div><p class="settings-note">Le test te permet de t’entendre dans ta sortie sélectionnée, sans transmettre à la team. Utilise de préférence un casque. Clique sur la jauge ou glisse le marqueur blanc pour régler la gate.</p></div></section><section class="panel"><div class="panel-heading">Profil d’entrée audio</div><div class="panel-body"><label class="field"><span>Traitement de la voix</span><select id="audio-profile"><option value="standard" ${state.settings.audioProfile==='standard'?'selected':''}>Standard · réduction du bruit et de l’écho</option><option value="studio" ${state.settings.audioProfile==='studio'?'selected':''}>Studio · aucun traitement</option><option value="custom" ${state.settings.audioProfile==='custom'?'selected':''}>Personnalisé</option></select></label>${audioToggle('noiseSuppression','Suppression du bruit','Réduction du bruit intégrée à WebRTC.')}${audioToggle('echoCancellation','Annulation d’écho','Réduit le retour de tes haut-parleurs dans le micro.')}<details class="advanced-audio"><summary>Paramètres avancés</summary>${audioToggle('autoGainControl','Gain automatique','Ajuste le niveau de capture avant le volume du micro.')}</details><p class="settings-note krisp-note">Krisp n’est pas inclus. Si tu utilises déjà l’application Krisp sur Windows, tu peux sélectionner son microphone virtuel dans la liste.</p></div></section><section class="panel"><div class="panel-heading">Sons du vocal</div><div class="panel-body"><label class="check"><input id="notification-sounds" type="checkbox" ${state.settings.notificationSounds?'checked':''}>Connexion, départs et déplacements</label>${volumeField('soundsVolume','Volume des notifications')}<p class="settings-note">Un son accompagne ta connexion, ta sortie et les déplacements. Tu entends aussi l’arrivée ou le départ d’un joueur de ton vocal.</p>${button('Tester le son','soundTest','','ghost')}</div></section>`;}
function audioToggle(key,label,note){return `<label class="audio-toggle"><span><strong>${label}</strong><small>${note}</small></span><input type="checkbox" data-audio-toggle="${key}" ${state.settings[key]?'checked':''}><span class="switch-track" aria-hidden="true"></span></label>`;}
async function refreshAudioDevices(){
 if(deviceLoading||!state)return false;deviceLoading=true;const accountId=state.currentUserId;let probe;
 const status=$('#audio-device-status');if(status)status.textContent='Recherche…';
 try{
  let devices=await navigator.mediaDevices.enumerateDevices();
  if(!voice.stream&&!stream&&!devices.some(d=>d.kind==='audioinput'&&d.label)){
   probe=await navigator.mediaDevices.getUserMedia({audio:true,video:false});devices=await navigator.mediaDevices.enumerateDevices();
  }
  if(state?.currentUserId!==accountId)return;
  micDevices=audioDeviceOptions(devices,'audioinput');outputDevices=audioDeviceOptions(devices,'audiooutput');
  const input=$('#mic-select'),output=$('#output-select');
  if(input)input.innerHTML=deviceOptions(micDevices,state.settings.mic,'Microphone');
  if(output)output.innerHTML=deviceOptions(outputDevices,state.settings.output,'Sortie audio');
  if(status)status.textContent=micDevices.length+' micro(s) · '+outputDevices.length+' sortie(s)';return true;
 }catch(e){if(status)status.textContent=e.name==='NotAllowedError'?'Autorise l’accès au micro dans Windows.':'Périphériques indisponibles. Réessaie.';}
 finally{probe?.getTracks().forEach(t=>t.stop());deviceLoading=false;}
}
navigator.mediaDevices?.addEventListener('devicechange',async()=>{
 if(!await refreshAudioDevices()||!state)return;
 const values={};if(state.settings.mic&&!micDevices.some(d=>d.deviceId===state.settings.mic))values.mic='';if(state.settings.output&&!outputDevices.some(d=>d.deviceId===state.settings.output))values.output='';
 if(Object.keys(values).length){try{stopMic();await dispatch({type:'settings',values});toast('Périphérique débranché : retour au périphérique Windows par défaut.');}catch(e){toast(friendlyError(e),true);}}
});
function syncSettingsControls(){
 for(const input of document.querySelectorAll('[data-setting]')){const key=input.dataset.setting;if(state.settings[key]!==undefined)input.value=state.settings[key];}
 for(const output of document.querySelectorAll('[data-volume-for]'))output.value=state.settings[output.dataset.volumeFor]+' %';
 for(const output of document.querySelectorAll('[data-vad-threshold]'))output.value=state.settings.vadThresholdDb+' dB';
 const marker=$('#mic-threshold');if(marker)marker.style.left=meterPercent(state.settings.vadThresholdDb)+'%';
 for(const [id,key]of [['mic-select','mic'],['output-select','output'],['audio-profile','audioProfile']]){const input=$('#'+id);if(input)input.value=state.settings[key];}
 for(const input of document.querySelectorAll('[data-audio-toggle]'))input.checked=state.settings[input.dataset.audioToggle];
 for(const [id,key]of [['ducking','ducking'],['notification-sounds','notificationSounds']]){const input=$('#'+id);if(input)input.checked=state.settings[key];}
 const testButton=$('[data-action=mic]');if(testButton)testButton.textContent=stream&&micMode==='test'?'Arrêter le test':'Test du micro';const testStatus=$('#mic-status');if(testStatus)testStatus.textContent=stream?micMode==='test'?'Test actif · retour audio dans ta sortie sélectionnée':'Détection locale active · aucun son transmis':voice.enabled?'Niveau du microphone en vocal':'Microphone arrêté';
 if(micMonitor){micMonitor.volume=state.settings.outputVolume/100;if(micMonitor.setSinkId&&micMonitor.sinkId!==state.settings.output)micMonitor.setSinkId(state.settings.output||'').catch(e=>toast(friendlyError(e),true));}
}
document.addEventListener('input',e=>{if(!e.target.dataset.setting)return;const key=e.target.dataset.setting,value=Number(e.target.value);const output=document.querySelector(`[data-volume-for="${key}"]`);if(output)output.value=value+' %';if(key==='inputVolume'&&micGraph)micGraph.gain.gain.value=value/100;if(key==='outputVolume'&&micMonitor)micMonitor.volume=value/100;if(key==='vadThresholdDb'){gatePreview=value;voice.vadPreview=value;for(const output of document.querySelectorAll('[data-vad-threshold]'))output.value=value+' dB';const marker=$('#mic-threshold');if(marker)marker.style.left=meterPercent(value)+'%';}});

function voiceSettings(){return `<section class="panel"><div class="panel-heading">Transmission & écoute</div><div class="panel-body"><label class="field"><span>Parler à la squad / au briefing</span><select data-voice-mode aria-label="Mode vocal squad / briefing"><option value="vad" ${voice.mode==='vad'?'selected':''}>Détection de voix</option><option value="ptt" ${voice.mode==='ptt'?'selected':''}>Push-to-talk · maintenir une touche</option></select></label><p class="settings-note">${voice.mode==='vad'?'Le micro s’ouvre quand ta voix est détectée et se ferme pendant les silences.':'Maintiens '+escape(voice.keyLabel('primary'))+' pour parler.'} Les leaders et les annonces restent en push-to-talk.</p><label class="field vad-threshold-field"><span>Seuil de détection <output data-vad-threshold>${state.settings.vadThresholdDb} dB</output></span><input type="range" min="-65" max="-20" step="1" value="${state.settings.vadThresholdDb}" data-setting="vadThresholdDb" aria-label="Seuil de détection"><small>À gauche : capte les voix faibles. À droite : ignore davantage le bruit de fond. Réglage par défaut : −48 dB. Utilise le test du micro en parlant normalement.</small></label><div class="audio-columns">${volumeField('squadVolume','Volume squad / briefing')}${volumeField('leadersVolume','Volume leaders / annonces')}</div><label class="check"><input id="ducking" type="checkbox" ${state.settings.ducking?'checked':''}>Baisser la squad quand les leaders parlent</label></div></section>`;}
function shortcutsPanel(){return `<section class="panel"><div class="panel-heading">Raccourcis vocaux</div><div class="panel-body"><p class="settings-note">Choisis un raccourci, appuie sur une touche ou un bouton de souris, puis valide avec Entrée.</p>${[['primary','Squad / briefing','Parler à ton escouade ou au briefing.'],['leaders','Leaders','Coordination entre chefs et adjoints.'],['broadcast','Annonce générale','Réservée au commandement.']].map(([kind,label,note])=>`<div class="shortcut-row"><div><strong>${label}</strong><p class="subtext">${note}</p></div>${button(escape(voice.keyLabel(kind)),'shortcut',`data-kind="${kind}" aria-label="Modifier le raccourci ${label}"`,'shortcut-key')}</div>`).join('')}<p class="subtext">Les trois raccourcis doivent être différents. Clavier, clic molette et boutons latéraux fonctionnent aussi lorsque tu joues.</p></div></section>`;}
function chooseSlot(q){
 if(!q||membership(state))return toast('Quitte d’abord ton escouade actuelle.',true);
 const free=q.slots.filter(t=>!t.playerId);if(!free.length)return toast('Cette escouade est complète.',true);
 showDialog('Rejoindre '+q.name,`<p class="dialog-description">Choisis ton poste parmi les places disponibles.</p><label class="field"><span>Poste</span><select name="slot" required>${free.map((t,i)=>`<option value="${escape(t.id)}">${escape(t.role)} · place ${i+1}</option>`).join('')}</select></label>`,'Rejoindre',async data=>{await dispatch({type:'join',squadId:q.id,slotId:data.get('slot')},'Tu as rejoint '+q.name+'.');});
}
async function shortcutForm(kind){
 let candidate=null;
 await voice.captureShortcut(true);
 showDialog('Choisir un raccourci',`<p class="dialog-description">Appuie sur une touche ou clique dans le champ avec le bouton de souris souhaité (clics, molette, boutons latéraux). Valide avec Entrée. Échap annule.</p><label class="field"><span>Touche ou bouton de souris</span><input id="shortcut-capture" readonly placeholder="Touche ou bouton de souris…" autofocus></label><p id="shortcut-hint" class="subtext">Le micro est suspendu pendant la saisie.</p>`,'Enregistrer',async()=>{
  if(!candidate)throw new Error('Appuie sur une touche ou un bouton de souris avant de valider.');
  const keys={...voice.keys,[kind]:candidate.key};validateKeys(keys);
  await voice.configure({keys,labels:{...voice.keyLabels,[kind]:candidate.label}});render();toast('Raccourci enregistré.');
 });
 const input=$('#shortcut-capture');input.focus();
 const select=value=>{candidate=value;input.value=candidate?.label||'';$('#shortcut-hint').textContent=candidate?'Entrée pour confirmer.':'Ce raccourci n’est pas disponible.';};
 input.onmousedown=e=>{e.preventDefault();e.stopPropagation();input.focus();select(captureMouse(e));};
 for(const type of ['mouseup','auxclick','contextmenu'])input.addEventListener(type,e=>{e.preventDefault();e.stopPropagation();});
 input.onkeydown=e=>{
  if(e.key==='Escape'){e.preventDefault();modal.close();return;}
  e.preventDefault();if(e.repeat)return;
  if(e.key==='Enter'&&candidate){$('#dialog-form').requestSubmit();return;}
  select(captureKey(e));
 };
 modal.addEventListener('close',()=>voice.captureShortcut(false).catch(error=>toast(friendlyError(error),true)),{once:true});
}
function voiceSidebar(){return `<div class="voice-sidebar"><div class="voice-dock-heading"><span class="voice-connection-icon">${icon('radio')}</span><div class="voice-dock-info"><strong data-voice-status>Vocal déconnecté</strong><span data-voice-label></span></div>${button(icon('logout'),'voiceConnect','data-icon-only="1" aria-label="Rejoindre le vocal" title="Rejoindre le vocal"','voice-dock-connect')}</div><div class="voice-dock-transmission">${speaking(state.currentUserId)}<span data-voice-target>Microphone au repos</span></div><div class="voice-controls">${button(icon('mic'),'voiceMute','aria-label="Couper mon micro" aria-pressed="false" title="Couper mon micro"')}${button(icon('headset'),'voiceDeafen','aria-label="Couper le son" aria-pressed="false" title="Couper le son"')}${button(icon('settings'),'audio','aria-label="Réglages audio" title="Réglages audio"')}</div><p data-voice-error class="error-text"></p></div>`;}
function updateVoiceDock(){
 const connected=voice.enabled&&!voice.connecting&&voice.rooms.get('primary')?.room.state==='connected'&&!voice.networkDown;
 const top=$('[data-top-voice-status]');if(top)top.textContent=shared?connected?'Vocal connecté':voice.connecting?'Connexion vocale…':'Serveur de la team':'Mode hors ligne';
 const dock=$('.voice-sidebar');if(dock){dock.classList.toggle('is-connected',connected);dock.classList.toggle('is-transmitting',connected&&voice.speaking);}
 const status=$('[data-voice-status]');if(status)status.textContent=voice.networkDown?'Connexion interrompue':voice.connecting?'Connexion…':connected?'Voix connectée':'Vocal déconnecté';
 const tx=$('[data-voice-target]');if(tx)tx.textContent=voice.deafened?'Casque et micro coupés':voice.muted?'Micro coupé':voice.speaking?'Tu parles → '+(voice.rooms.get(voice.transmitting)?.channel.label||voice.label):voice.mode==='ptt'?'Push-to-talk · '+voice.keyLabel('primary'):'Détection de voix';
 const connect=$('.voice-dock-connect');if(connect){const voiceIcon=voice.enabled?'logout':'headset';if(connect.dataset.voiceIcon!==voiceIcon){connect.dataset.voiceIcon=voiceIcon;connect.innerHTML=icon(voiceIcon);}connect.setAttribute('aria-label',voice.enabled?'Quitter le vocal':membership(state)?'Rejoindre mon vocal':'Rejoindre l’accueil');connect.title=connect.getAttribute('aria-label');}
 for(const b of document.querySelectorAll('[data-squad-connect]')){const q=squad(b.dataset.squadConnect),here=connected&&voice.rooms.get('primary')?.channel.squadId===q?.id;const op=q&&operationForSquad(state,q.id),brief=op?.briefingSquadIds.includes(q.id);const label=here?'Connectée':'Connexion';if(b.dataset.voiceButtonLabel!==label){b.dataset.voiceButtonLabel=label;b.innerHTML=icon('headset')+label;}b.disabled=voice.connecting||here;b.classList.toggle('vocal-joined',here);b.title=brief?'Vocal de briefing de '+op.name:'Vocal de '+q.name;}
 for(const row of document.querySelectorAll('.rail-squad')){const here=connected&&voice.rooms.get('primary')?.channel.squadId===row.dataset.id,badge=row.querySelector('.rail-status');if(here&&!badge)row.insertAdjacentHTML('beforeend','<i class="rail-status" aria-label="Vocal connecté"></i>');if(!here&&badge)badge.remove();}
 const lobbyConnect=$('[data-action=voiceLobby]');if(lobbyConnect){const here=connected&&!voice.rooms.get('primary')?.channel.squadId;lobbyConnect.textContent=here?'Accueil rejoint':'Rejoindre l’accueil';lobbyConnect.disabled=voice.connecting||here;}
}
function communicationPage(){
 const primary=voice.rooms.get('primary')?.channel.label||membership(state)?.name||'Accueil';
 return `<div class="page"><div class="page-heading"><div><h1>Communications</h1><p class="subtext">${shared?'Vocal de la team · squad, briefing et radio leaders.':'Connecte-toi au serveur de la team pour utiliser le vocal.'}</p></div>${shared?button(voice.enabled?'Quitter le vocal':'Rejoindre le vocal','voiceConnect','','gold'):button('Choisir le serveur','serverSettings','','gold')}</div><div class="diagram">${[['primary','squad',primary,'Votre squad, ou le briefing lorsque votre chef vous rassemble.',true],['leaders','radio','Réseau leaders','Chefs, adjoints et commandants de la team.',leaderAccess(state)],['broadcast','users','Annonce générale','Tout le monde écoute ; seul le commandement peut parler.',me().commander]].map(([kind,ic,title,text,allowed])=>`<section class="network-card">${icon(ic)}<h3 ${kind==='primary'?'data-voice-label':''}>${escape(title)}</h3><p>${text}</p><button class="btn radio-ptt" data-ptt="${kind}" data-ptt-allowed="${allowed?1:0}" ${!voice.enabled||!allowed?'disabled':''}>Maintenir ${escape(voice.keyLabel(kind))} pour parler</button></section>`).join('')}</div><p class="subtext">${shared?'Les indicateurs jaunes correspondent à l’activité transmise. Les canaux sont autorisés par le serveur.':'Le mode hors ligne conserve les outils de préparation ; aucune voix n’est transmise.'}</p>${voice.error?`<div class="notice">${escape(voice.error)} ${button('Activer le son','voiceAudio')}</div>`:''}</div>`;
}
async function onSharedEvent(event){
 if(event.type==='sessionExpired'){await voice.disconnect();channelsView.reset();state=null;document.body.classList.remove('channel-layout');await start();toast('Session expirée ou compte connecté sur une autre machine.');return;}
 if(channelExperiment&&state&&(event.type==='chat'||event.type==='chatMutation'||event.type==='chatChannels')){if(event.type==='chat'||event.type==='chatMutation')channelsView.event(event);else channelsView.refresh(state);return;}
 if(event.type==='voiceState'){remoteVoiceStates.set(event.userId,event);updateVoiceUI();return;}
 if(event.type==='activity'){remoteSpeaking.set(event.userId,event);updateVoiceUI();return;}
 if(event.type==='network'){networkOnline=event.connected;if(!event.connected){remoteVoiceStates.clear();remoteSpeaking.clear();voice.networkDown=true;voice.applyTransmit();}updateVoiceUI();return;}
 if(event.type==='state'&&state){
  const stateChanged=JSON.stringify(state)!==JSON.stringify(event.state),priorSquad=membership(state)?.id;
  state=event.state;if(channelExperiment&&shared&&!priorSquad&&membership(state)){roomMode='text';channelsView.selectPending('squad:'+membership(state).id);}remoteVoiceStates=new Map((event.voiceStates||[]).map(v=>[v.userId,v]));voiceUsers=event.voiceUsers||[];onlineIds=event.onlineIds||[];voice.observePresence(voiceUsers,state.currentUserId);
  if(!modal.open&&stateChanged)render();else updateVoiceUI();
  if(channelExperiment&&shared&&stateChanged)channelsView.refresh(state);
  if(voice.enabled&&(stateChanged||voice.networkDown))voice.sync(state.settings).then(()=>{voice.networkDown=false;voice.applyTransmit();}).catch(e=>{voice.error=friendlyError(e);updateVoiceUI();});
 }
}
window.desktop?.onNetwork(onSharedEvent);
document.addEventListener('pointerdown',event=>{const b=event.target.closest('[data-ptt]');if(!b||b.disabled)return;b.setPointerCapture(event.pointerId);voice.setPointer(b.dataset.ptt,true);});
for(const type of ['pointerup','pointercancel'])document.addEventListener(type,event=>{const b=event.target.closest('[data-ptt]');if(b)voice.setPointer(b.dataset.ptt,false);else voice.releasePointers();});
window.addEventListener('blur',()=>voice.releasePointers());
window.addEventListener('pagehide',()=>voice.disconnect());


function updateMessage(){return ({available:'La version '+updateState.version+' est disponible.',checking:'Recherche de mises à jour…',downloading:'Téléchargement de la version '+updateState.version+' · '+updateState.percent+' %',ready:'Version '+updateState.version+' prête. Elle sera installée au prochain lancement.',installing:'Installation de la mise à jour… UMBRA va redémarrer.',current:'UMBRA est à jour.',portable:'Installe UMBRA depuis le site pour activer les mises à jour automatiques.',error:'La mise à jour n’a pas pu être effectuée. La version actuelle reste disponible.'})[updateState.phase]||'';}
function updatePanel(){return `<section class="panel"><div class="panel-heading">Application · ${escape(appVersion)}</div><div class="panel-body" id="updates-panel-body">${updatePanelBody()}</div></section>`;}
function updatePanelBody(){return `<p class="settings-note" data-update-status>${escape(updateMessage())}</p>${updateState.installed?`<div class="setting-actions">${button('Vérifier les mises à jour','updatesCheck',['checking','downloading','installing'].includes(updateState.phase)?'disabled':'','ghost')}${updateState.phase==='ready'?button('Installer et redémarrer','updatesInstall','','gold'):''}</div><p class="subtext">Vérification au lancement et toutes les minutes pendant l’utilisation. Une mise à jour ne coupe pas ton vocal sans action de ta part. Tes comptes et réglages sont conservés.</p>`:''}`;}
function renderUpdateStartup(){
 $('#app').innerHTML=`${titlebar()}<main class="update-layout"><div class="brand">${brand}<div><div class="brand-name">UMBRA</div><div class="brand-sub">WARDOGS COMPANION</div></div></div><h1>${updateState.phase==='checking'?'Préparation d’UMBRA':'Mise à jour d’UMBRA'}</h1><p role="status">${escape(updateMessage())}</p><div class="update-progress" role="progressbar" aria-label="Mise à jour" aria-valuemin="0" aria-valuemax="100" aria-valuenow="${updateState.percent||0}"><span style="width:${updateState.phase==='checking'?12:updateState.percent||0}%"></span></div><small>Tes comptes et tes réglages restent en place.</small></main>`;
}
function updateTopButton(){const el=$('[data-top-update]');if(!el)return;const visible=updateState.installed&&updateState.version&&['available','downloading','ready','error'].includes(updateState.phase);el.innerHTML=visible?`<button class="btn gold top-update-button" data-action="updateNow" ${updateState.phase==='downloading'?'disabled':''} title="Installer UMBRA ${escape(updateState.version)} et redémarrer">${icon('download')}${updateState.phase==='downloading'?'Téléchargement · '+updateState.percent+' %':'Mise à jour disponible'}</button>`:'';}
window.desktop?.onUpdate(value=>{updateState=value;if(value.startup&&['checking','downloading','installing','ready'].includes(value.phase))renderUpdateStartup();else{const el=$('#updates-panel-body');if(el)el.innerHTML=updatePanelBody();updateTopButton();}});

async function start(){
 try{if(!window.desktop)throw new Error('Ouvre UMBRA.exe pour accéder à tes comptes.');const info=await window.desktop.networkInfo();appVersion=info.version||appVersion;shared=info.shared;serverAddress=info.url;updateState=await window.desktop.updatesStatus();if(updateState.startup&&updateState.installed)renderUpdateStartup();await window.desktop.updatesReady();const status=await window.desktop.authStatus();authMode=status.needsRegistration?'register':'login';const resumed=await window.desktop.resumeSession();if(resumed)acceptSession(resumed);else renderAuth();}
 catch(error){renderAuth(friendlyError(error));$('#auth-form [type=submit]').disabled=true;}
}
start();

// Pointer interaction on the meter is independent of the experimental channel layout.
let gateDrag=null;
function moveGate(event){
 if(!gateDrag)return;const rect=gateDrag.bar.getBoundingClientRect(),db=Math.max(-65,Math.min(-20,Math.round((event.clientX-rect.left)/rect.width*72-72)));
 gateDrag.input.value=db;gateDrag.input.dispatchEvent(new Event('input',{bubbles:true}));
}
document.addEventListener('pointerdown',event=>{
 const bar=event.target.closest('[data-gate-bar]');if(!bar||event.button!==0)return;
 const input=bar.querySelector('#gate-on-meter');if(!input)return;event.preventDefault();gateDrag={bar,input,id:event.pointerId};bar.setPointerCapture(event.pointerId);input.focus({preventScroll:true});moveGate(event);
});
document.addEventListener('pointermove',event=>{if(gateDrag&&event.pointerId===gateDrag.id)moveGate(event);});
document.addEventListener('pointerup',event=>{if(!gateDrag||event.pointerId!==gateDrag.id)return;moveGate(event);const input=gateDrag.input;gateDrag=null;input.dispatchEvent(new Event('change',{bubbles:true}));});
function cancelGateDrag(){gateDrag=null;gatePreview=null;voice.vadPreview=null;if(state){for(const range of document.querySelectorAll('[data-setting=vadThresholdDb]'))range.value=state.settings.vadThresholdDb;const marker=$('#mic-threshold');if(marker)marker.style.left=meterPercent(state.settings.vadThresholdDb)+'%';const out=$('[data-vad-threshold]');if(out)out.textContent=state.settings.vadThresholdDb+' dB';}}
document.addEventListener('pointercancel',cancelGateDrag);
window.addEventListener('blur',()=>{if(gateDrag)cancelGateDrag();});
